mapper.select:
SELECT A.ID AS ALERT_ID ,A.STOCK_ID ,S.SYMBOL ,S.NAME ,A.CONDITION ,A.TARGET_PRICE ,A.STATUS ,A.SENT_PRICE ,(EXTRACT(EPOCH FROM A.SENT_DAY) * 1000)::BIGINT AS SENT_AT ,(EXTRACT(EPOCH FROM A.INS_DAY) * 1000)::BIGINT AS INS_AT FROM T_PRICE_ALERT A JOIN T_STOCK S ON S.ID = A.STOCK_ID WHERE 1=1 AND A.USER_ID = #{userId}
AND A.STOCK_ID = #{stockId}
ORDER BY A.ID DESC

mapper.insert:
INSERT INTO T_PRICE_ALERT (
       USER_ID
      ,STOCK_ID
      ,CONDITION
      ,TARGET_PRICE
)
SELECT  #{userId}
       ,S.ID
       ,#{condition}
       ,#{targetPrice}
  FROM T_STOCK S
 WHERE 1=1
   AND S.ID = #{stockId}

mapper.delete:
DELETE FROM T_PRICE_ALERT
 WHERE 1=1
   AND ID      = #{alertId}
   AND USER_ID = #{userId}
